package com.vib.cms.rbac.service;
import com.vib.cms.rbac.api.*;import org.springframework.jdbc.core.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.sql.Timestamp;import java.time.Instant;import java.util.*;
@Service public class RbacService {
 private final JdbcTemplate jdbc;public RbacService(JdbcTemplate jdbc){this.jdbc=jdbc;}
 private static final RowMapper<Map<String,Object>> MAP=(rs,n)->{var m=new LinkedHashMap<String,Object>();var md=rs.getMetaData();for(int i=1;i<=md.getColumnCount();i++)m.put(md.getColumnLabel(i),rs.getObject(i));return m;};
 public List<Map<String,Object>> users(String q,String status,int page,int size){int off=Math.multiplyExact(page,size);String k="%"+(q==null?"":q.toLowerCase())+"%";return jdbc.query("select id,username,email,display_name,identity_source,external_subject,status,created_at,updated_at from app_users where (?='' or status=?) and (lower(username) like ? or lower(coalesce(email,'')) like ? or lower(coalesce(display_name,'')) like ?) order by username limit ? offset ?",MAP,status==null?"":status,status==null?"":status,k,k,k,size,off);}
 public Map<String,Object> user(UUID id){return jdbc.queryForObject("select id,username,email,display_name,identity_source,external_subject,status,created_at,updated_at from app_users where id=?",MAP,id);}
 @Transactional public Map<String,Object> upsertUser(String username,String email,String name,String source,String subject,String status){jdbc.update("insert into app_users(username,email,display_name,identity_source,external_subject,status) values (?,?,?,?,?,?) on conflict(identity_source,external_subject) do update set username=excluded.username,email=excluded.email,display_name=excluded.display_name,status=excluded.status,updated_at=now()",username,email,name,source,subject,status);return jdbc.queryForObject("select id,username,email,display_name,identity_source,external_subject,status,created_at,updated_at from app_users where identity_source=? and external_subject=?",MAP,source,subject);}
 @Transactional public Map<String,Object> updateUser(UUID id,UserRequest r){int n=jdbc.update("update app_users set username=?,email=?,display_name=?,status=?,updated_at=now() where id=?",r.username(),r.email(),r.displayName(),r.status(),id);if(n==0)throw new NoSuchElementException("User not found");return user(id);}
 public List<Map<String,Object>> roles(){return jdbc.query("select id,code,name,description,is_system,created_at from roles order by code",MAP);}
 public List<Map<String,Object>> permissions(){return jdbc.query("select id,resource_type,action_code,state_code,scope_type,effect,description from permissions order by resource_type,action_code",MAP);}
 @Transactional public Map<String,Object> createPermission(PermissionRequest r){String res=r.resourceType().toUpperCase(),act=r.actionCode().toUpperCase(),st=r.stateCode()==null?null:r.stateCode().toUpperCase(),scope=r.scopeType().toUpperCase(),effect=r.effect().toUpperCase();jdbc.update("insert into permissions(resource_type,action_code,state_code,scope_type,effect,description) values (?,?,?,?,?,?) on conflict do nothing",res,act,st,scope,effect,r.description());return jdbc.queryForObject("select id,resource_type,action_code,state_code,scope_type,effect,description from permissions where resource_type=? and action_code=? and state_code is not distinct from ? and scope_type=? and effect=?",MAP,res,act,st,scope,effect);}
 @Transactional public void attachPermission(UUID role,UUID permission){jdbc.update("insert into role_permissions(role_id,permission_id) values (?,?) on conflict do nothing",role,permission);}
 @Transactional public void assign(AssignmentRequest r,String actor){if(r.expiresAt()!=null&&!r.expiresAt().isAfter(Instant.now()))throw new IllegalArgumentException("expiresAt must be in the future");jdbc.update("insert into user_product_roles(user_id,product_id,role_id,assigned_by,assigned_at,expires_at) values (?,?,?,?,now(),?) on conflict(user_id,product_id,role_id) do update set assigned_by=excluded.assigned_by,assigned_at=now(),expires_at=excluded.expires_at",r.userId(),r.productId(),r.roleId(),actor,r.expiresAt()==null?null:Timestamp.from(r.expiresAt()));}
 @Transactional public void revoke(UUID u,UUID p,UUID r){jdbc.update("delete from user_product_roles where user_id=? and product_id=? and role_id=?",u,p,r);}
 public List<Map<String,Object>> assignments(UUID id){return jdbc.query("select x.user_id,u.username,x.product_id,p.code product_code,p.name product_name,x.role_id,r.code role_code,r.name role_name,x.assigned_by,x.assigned_at,x.expires_at from user_product_roles x join app_users u on u.id=x.user_id join products p on p.id=x.product_id join roles r on r.id=x.role_id where x.user_id=? order by p.code,r.code",MAP,id);}
 public boolean allowed(String user,UUID product,String resource,String action,String state){String sql="select exists(select 1 from app_users u join user_product_roles x on x.user_id=u.id join roles r on r.id=x.role_id join role_permissions rp on rp.role_id=r.id join permissions p on p.id=rp.permission_id where (u.username=? or u.external_subject=?) and u.status='ACTIVE' and x.product_id=? and (x.expires_at is null or x.expires_at>now()) and p.resource_type=? and p.action_code=? and (p.state_code is null or p.state_code=?) and p.scope_type in ('PRODUCT','RESOURCE') and p.effect='ALLOW' and not exists(select 1 from role_permissions z join permissions d on d.id=z.permission_id where z.role_id=r.id and d.resource_type=p.resource_type and d.action_code=p.action_code and (d.state_code is null or d.state_code=?) and d.effect='DENY')) or exists(select 1 from app_users u join user_product_roles x on x.user_id=u.id join roles r on r.id=x.role_id join role_permissions rp on rp.role_id=r.id join permissions p on p.id=rp.permission_id where (u.username=? or u.external_subject=?) and u.status='ACTIVE' and (x.expires_at is null or x.expires_at>now()) and p.scope_type='GLOBAL' and p.effect='ALLOW' and p.resource_type=? and p.action_code=?)";return Boolean.TRUE.equals(jdbc.queryForObject(sql,Boolean.class,user,user,product,resource.toUpperCase(),action.toUpperCase(),state==null?"":state.toUpperCase(),state==null?"":state.toUpperCase(),user,user,resource.toUpperCase(),action.toUpperCase()));}
 public void requireAdmin(String user){Boolean ok=jdbc.queryForObject("select exists(select 1 from app_users u join user_product_roles x on x.user_id=u.id join roles r on r.id=x.role_id where (u.username=? or u.external_subject=?) and u.status='ACTIVE' and r.code='SYSTEM_ADMIN' and (x.expires_at is null or x.expires_at>now()))",Boolean.class,user,user);if(!Boolean.TRUE.equals(ok))throw new org.springframework.security.access.AccessDeniedException("SYSTEM_ADMIN role required");}
 @Transactional public void audit(String actor,String action,String type,UUID id,UUID product,Object before,Object after){jdbc.update("insert into audit_logs(product_id,actor_username,action_code,resource_type,resource_id,before_data,after_data) values (?,?,?,?,?,?::jsonb,?::jsonb)",product,actor,action,type,id,json(before),json(after));}
 private String json(Object o){if(o==null)return null;try{return new tools.jackson.databind.ObjectMapper().writeValueAsString(o);}catch(Exception e){return "{\"error\":\"serialization\"}";}}
}